const fs = require('fs');
const path = require('path');

// Get all files with `new APIError(` from grep
const { execSync } = require('child_process');
const grepResult = execSync(
  `grep -rn "new APIError(" --include="*.ts" -l .`,
  { encoding: 'utf-8' }
).trim().split('\n').filter(Boolean);

// Skip the APIError.ts definition itself
const files = grepResult.filter(f => !f.endsWith('src/errors/APIError.ts'));

function getErrorCode(message, status) {
  // Try to determine error code from status code
  if (status === 400 || status === 'httpStatus.BAD_REQUEST') return 'BAD_REQUEST';
  if (status === 401 || status === 'httpStatus.UNAUTHORIZED') return 'UNAUTHORIZED';
  if (status === 403 || status === 'httpStatus.FORBIDDEN') return 'FORBIDDEN';
  if (status === 404 || status === 'httpStatus.NOT_FOUND') return 'NOT_FOUND';
  if (status === 413 || status === 'httpStatus.REQUEST_ENTITY_TOO_LARGE') return 'REQUEST_ENTITY_TOO_LARGE';
  if (status === 418) return 'TEAPOT';
  if (status === 422) return 'UNPROCESSABLE_ENTITY';
  if (status === 423 || status === 'httpStatus.LOCKED') return 'LOCKED';
  if (status === 500 || status === 'httpStatus.INTERNAL_SERVER_ERROR') return 'INTERNAL_ERROR';

  // Try to determine from message content
  const msgLower = (message || '').toLowerCase();
  if (msgLower.includes('not found') || msgLower.includes('was not found') || msgLower.includes('not exist') || msgLower.includes('can\'t be found')) return 'NOT_FOUND';
  if (msgLower.includes('unauthorized') || msgLower.includes('not authorized')) return 'UNAUTHORIZED';
  if (msgLower.includes('forbidden') || msgLower.includes('not allowed') || msgLower.includes('disabled')) return 'FORBIDDEN';
  if (msgLower.includes('missing') || msgLower.includes('required')) return 'BAD_REQUEST';
  if (msgLower.includes('invalid')) return 'BAD_REQUEST';
  if (msgLower.includes('not supported')) return 'NOT_SUPPORTED';
  if (msgLower.includes('timeout')) return 'TIMEOUT';
  if (msgLower.includes('upload') || msgLower.includes('file')) return 'FILE_ERROR';

  return 'INTERNAL_ERROR';
}

for (const filePath of files) {
  let content = fs.readFileSync(filePath, 'utf-8');

  // Match new APIError( ... ) patterns
  // We need to handle both single-line and multi-line cases
  // Strategy: find each `new APIError(` and insert the error code as first arg

  let modified = false;

  // Handle: new APIError('...
  // or: new APIError(`...
  // or: new APIError(variable...
  // We need to add an error code string as the first argument

  // Pattern: new APIError( followed by content
  const regex = /new APIError\(\s*\n?\s*/g;
  let match;
  const replacements = [];

  while ((match = regex.exec(content)) !== null) {
    const startIdx = match.index + match[0].length;

    // Look at what comes after to determine the error code
    const rest = content.substring(startIdx, startIdx + 200);

    // Extract the first argument (message)
    let firstArg = '';
    if (rest.startsWith("'") || rest.startsWith('"') || rest.startsWith('`')) {
      const quote = rest[0];
      let i = 1;
      let depth = 0;
      while (i < rest.length) {
        if (rest[i] === '\\') { i += 2; continue; }
        if (quote === '`' && rest[i] === '$' && rest[i+1] === '{') { depth++; i += 2; continue; }
        if (depth > 0 && rest[i] === '}') { depth--; i++; continue; }
        if (depth === 0 && rest[i] === quote) break;
        i++;
      }
      firstArg = rest.substring(0, i + 1);
    } else {
      // Variable or expression
      firstArg = rest.split(/[,)]/)[0].trim();
    }

    // Try to find the second argument (status code)
    const afterFirstArg = rest.substring(firstArg.length).trim();
    let statusCode = null;
    if (afterFirstArg.startsWith(',')) {
      const statusStr = afterFirstArg.substring(1).trim().split(/[,)]/)[0].trim();
      if (/^\d+$/.test(statusStr)) {
        statusCode = parseInt(statusStr);
      } else {
        statusCode = statusStr;
      }
    }

    const errorCode = getErrorCode(firstArg, statusCode);

    replacements.push({
      index: match.index,
      original: match[0],
      replacement: `new APIError(\n${match[0].includes('\n') ? match[0].split('\n').pop() : '      '}'${errorCode}',\n${match[0].includes('\n') ? match[0].split('\n').pop() : '      '}`
    });
  }

  // Apply replacements in reverse order to preserve indices
  for (let i = replacements.length - 1; i >= 0; i--) {
    const r = replacements[i];
    content = content.substring(0, r.index) + r.replacement + content.substring(r.index + r.original.length);
    modified = true;
  }

  if (modified) {
    fs.writeFileSync(filePath, content);
    console.log(`Updated: ${filePath} (${replacements.length} replacements)`);
  }
}
