const fs = require('fs');
const { execSync } = require('child_process');

// Get all modified files
const modifiedFiles = execSync('git diff --name-only', { encoding: 'utf-8' }).trim().split('\n').filter(f => f.endsWith('.ts'));

for (const relPath of modifiedFiles) {
  let content = fs.readFileSync(relPath, 'utf-8');

  // Fix pattern: new APIError(\n{indent}'CODE',\n{indent}restOfArgs)
  // Where the original was a single-line call, we want to keep it single-line
  // Pattern: `new APIError(\n      'CODE',\n      'message'` where message was originally on same line as APIError(

  // Fix the common bad pattern where the script broke single-line calls into multi-line
  // Pattern: `new APIError(\n{spaces}'ERROR_CODE',\n{spaces}originalFirstArg`
  // We need to detect when the original was single-line vs multi-line

  // Strategy: look for `new APIError(\n{spaces}'CODE',\n{spaces}` followed by content that ends with `)` on same line
  // and collapse it back to single line

  // Fix 1: collapse `new APIError(\n{spaces}'CODE',\n{spaces}rest)` to `new APIError('CODE', rest)`
  // when rest is a single-line expression ending in )

  const lines = content.split('\n');
  const result = [];
  let i = 0;

  while (i < lines.length) {
    const line = lines[i];
    const match = line.match(/^(\s*)(.*?)new APIError\(\s*$/);

    if (match) {
      const baseIndent = match[1];
      const prefix = match[2];

      // Check if next line is the error code
      if (i + 1 < lines.length && lines[i + 1].trim().match(/^'[A-Z_]+',$/) && 
          i + 2 < lines.length) {
        const errorCode = lines[i + 1].trim().replace(/,$/, '');
        const restLine = lines[i + 2];
        const restTrimmed = restLine.trim();

        // Check if the rest is a single-line ending with )
        if (restTrimmed.endsWith(')') && !restTrimmed.startsWith('`') || 
            (restTrimmed.endsWith(')') && !restTrimmed.includes('\n'))) {
          // Check if the next line after is NOT a continuation (i.e., not more args)
          // It's single-line if restLine ends with just )
          if (restTrimmed.match(/^.*\)$/)) {
            result.push(`${baseIndent}${prefix}new APIError(${errorCode}, ${restTrimmed}`);
            i += 3;
            continue;
          }
        }

        // It's multi-line - normalize indentation
        // The error code line should be indented relative to the `new APIError(` line
        const innerIndent = baseIndent + (prefix ? '  ' : '  ');
        result.push(line); // keep the `new APIError(` line
        result.push(`${innerIndent}${errorCode},`);

        // Fix the rest of the args - they should use the same inner indent
        i += 2;
        while (i < lines.length) {
          const currentLine = lines[i];
          const currentTrimmed = currentLine.trim();

          if (currentTrimmed === '') {
            result.push(currentLine);
            i++;
            continue;
          }

          // Re-indent to match
          result.push(`${innerIndent}${currentTrimmed}`);
          i++;

          if (currentTrimmed.endsWith(')') || currentTrimmed.endsWith('),')) {
            break;
          }
        }
        continue;
      }
    }

    result.push(line);
    i++;
  }

  const newContent = result.join('\n');
  if (newContent !== content) {
    fs.writeFileSync(relPath, newContent);
    console.log(`Fixed formatting: ${relPath}`);
  }
}
